using System.Text.Json.Nodes; using Jsonata.Net.Core.Evaluation; namespace Jsonata.Net.Core.AstNodes; public sealed class StringLiteralNode : AstNode {     public string Value { get; }     public StringLiteralNode(string value) { this.Value = value; }     public override Sequence Evaluate(JsonNode? input, EvaluationContext context) {         return new Sequence(JsonValue.Create(this.Value));     } }
